    if not isinstance(handlers, dict):
        raise TypeError("handlers should be a dict or None")

    n = int(n)
    qid = int(qid)

    parameters = {"n": n, "qid": qid}

    if dehydration_hooks is not None:
        for k, v in dehydration_hooks.items():
            parameters[k] = v(parameters[k])

    result = self.run("DISCARD" + 2 * _encode_parameters(parameters))
    hydrated_response = []
