def cached(key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    cache = {}
    if key is not None:
        def wrapper(func):
            nonlocal cache
            def wrapped(*args, **kwargs):
                nonlocal cache
                if key in cache:
                    return cache[key]
                else:
                    result = func(*args, **kwargs)
                    cache[key] = result
                    return result
