def minimalBases(classes):
    """
    Reduce a list of base classes to its ordered minimum equivalent

    :param classes: list of base classes to reduce
    :return: ordered minimum equivalent list of base classes
    """
    # check if input is valid
    if not classes:
        raise ValueError("Input list of classes is empty")

    # create a new set to store the minimal base classes
    minimal_classes = set()

    # iterate through the list of classes and add them to the set
    for cls in classes:
        minimal_classes.add(cls)

    # iterate through the set and remove any class that is a subclass of another class in the set
    for cls in minimal_classes.copy():
        if any(issubclass(cls, other_cls) for other_cls in minimal_classes):
            minimal_classes.remove(cls)

    # return the ordered minimum equivalent list of base classes
    return list(minimal_classes)

