def _update_context(self, context):
    """
    Updates the context with the properties of the graph.
    """
    # Iterate over the error dictionaries
    for error_name, error_dict in context.error.items():
        # Check if the error dict has the "index" key
        if "index" in error_dict:
            # If so, update the index with the current error name
            error_dict["index"][error_name] = self.index

    # Update the context value with the fields of the graph
    for field in self.fields:
        # If the field is not in the context, add it
        if field not in context.value:
            context.value[field] = getattr(self, field)

    # Update the context value with the subfields of the graph
    for subfield, subfields in self.subfields.items():
        # If the subfield is not in the context, add it
        if subfield not in context.subvalues:
            context.subvalues[subfield] = {}

        # Iterate over the subfields and update the context accordingly
        for subfield_name in subfields:
            # If the subfield is not in the context, add it
            if subfield_name not in context.subvalues[subfield]:
                context.subvalues[subfield][subfield_name] = {}

            # Update the subfield with the current error name
            context.subvalues[subfield][subfield_name]["index"] = self.index

    return context

def integral(bins, edges):
    """Compute integral (scale for a histogram)."""
    # Handle invalid input
    if len(bins) != len(edges) - 1:
        raise ValueError("Invalid input: length of bins and edges do not match.")

    # Compute integral
    integral = 0
    for i in range(len(bins)):
        integral += bins[i] * (edges[i+1] - edges[i])

    return integral

