    if not isinstance(style, str):
        raise TypeError("Expected a string for 'style', got {type(style)} instead")

    # Handle null input
    if not pieces:
        return ""

    # Convert pieces to a list if necessary
    pieces = list(pieces)

    # Render the pieces based on the requested style
    if style == "flat":
        return ".".join(pieces)
    elif style == "comma-separated":
        return ", ".join(pieces)
    elif style == "underscore-separated":
        return "_".join(pieces)
    else:
        raise ValueError(f"Unsupported style: {style}")
