def register_vcs_handler(vcs, method):
    """
    Creates a decorator that marks a method as the handler of a version control system (VCS).

    :param vcs: A version control system.
    :param method: A method to decorate.
    :return: The decorated method.
    """

    if not isinstance(vcs, VCS):
        raise TypeError("Expected a VCS instance, but got {type(vcs)}")

    if not callable(method):
        raise TypeError("Expected a callable method, but got {type(method)}")

    @wraps(method)
    def wrapper(*args, **kwargs):
        try:
            return method(*args, **kwargs)
        except Exception as e:
            log = logging.getLogger('VCS')
            log.error(f"Error while handling VCS {vcs.name}: {e}")
            raise e from None

