import ruamel.yaml

def deep_merge_nodes(nodes):
    result = []

    for key, value in nodes:
        # If the value is not a MappingNode, simply append it to the result
        if not isinstance(value, ruamel.yaml.nodes.MappingNode):
            result.append((key, value))
            continue

        # Find the key in the existing mapping
        for i, (existing_key, existing_value) in enumerate(result):
            if existing_key and existing_key.value == key.value:
                if isinstance(existing_value, ruamel.yaml.nodes.MappingNode):
                    # If the value is also a MappingNode, merge the two maps recursively
                    result[i] = (existing_key, deep_merge_nodes([(existing_key, existing_value), (key, value)]))
                    break
                else:
                    # Replace the existing non-MappingNode value with the new non-MappingNode value
                    result[i] = (key, value)
                    break
        else:
            # No existing key found, simply append the new key and value
            result.append((key, value))

    return result

