            parse_error_list.append(logging.LogRecord(' -', logging.ERROR, ": Unable to open config file %s" % config_filename.__repr__()))
            continue
        except UnicodeDecodeError:
            config_parse_results_dict[config_filename.__repr__()] = dict()
            parse_error_list.append(logging.LogRecord(' -', logging.ERROR, ": Unable to decode config file %s" % config_filename.__repr__()))
            continue
        try:
            config_parse_results_dict[config_filename.__repr__()] = config_filename.parse()
            config_contents_dict[config_filename.__repr__()] = config_parse_results_dict[config_filename.__repr__()]["content"]
