            constants_for_instance_dict[config_filename.__repr__()] = config_parse_results_dict[config_filename.__repr__()]["constants"]
            flattened_config_dict = flatten_key_dict(config_for_instance_dict)
        except configparser.Error as e:
            config_parse_results_dict[config_filename.__repr__()] = {
                "content": config_parse_results_dict[config_filename.__repr__()],
                "instance": config_for_instance_dict,
                "constants": constants_for_instance_dict}
            parse_error_list.append(logging.LogRecord('__', logging.ERROR, ": Config file parse error: %s : %s" % (config_filename.__repr__, e)))
    flattened_result["ignore_missing_keys"] = flattened_config_dict
    flattened_result["parse_error_list"] = parse_error_list
    flattened_result["config_filenames"] = config_filenames
    flattened_result["overrides"] = overrides
    flattened_result["resolve_env"] = resolve_env
    parsed_output = flattened_result
    return (parsed_output, parse_error_list)

