def _verify(iface, candidate, tentative=False, vtype=None):
    # Verify that candidate claims it provides the interface
    if not tentative:
        if not iface.providedBy(candidate, False):
            raise zope.interface.Invalid(
                f"Candidate does not provide the interface {iface}")

    # Verify that candidate defines all necessary methods
    for method_name in iface.names:
        method_type = iface.getMethod(method_name)
        if not hasattr(candidate, method_name):
            raise zope.interface.Invalid(
                f"Candidate does not define method {method_name}")
        else:
            # Verify that method has the correct signature
            if method_type.getSignatureInformation() != \
                    inspect.signature(getattr(candidate, method_name)):
                raise zope.interface.Invalid(
                    f"Candidate defines method {method_name} with "
                    f"incorrect signature")

    # Verify that candidate defines all necessary attributes
    for attr_name in iface.names:
        attr_type = iface.getMethod(attr_name)
        if not hasattr(candidate, attr_name):
            raise zope.interface.Invalid(
                f"Candidate does not define attribute {attr_name}")
        else:
            # Verify that attribute has the correct type
            if attr_type != type(getattr(candidate, attr_name)):
                raise zope.interface.Invalid(
                    f"Candidate defines attribute {attr_name} with "
                    f"incorrect type")

    return True

def verifyObject(iface, candidate, tentative=False):
    try:
        if not tentative:
            iface_provided = iface.providedBy(candidate)
            if not iface_provided:
                raise zope.interface.Invalid("The candidate does not claim to provide the interface")
        methods = dir(candidate)
        for method_name in methods:
            method = getattr(candidate, method_name)
            method_sig = signature(method)
            if method_sig.parameters:
                parameters = {param.name for param in method_sig.parameters.values()}
                missing_params = parameters - method_sig.parameters.keys()
                if missing_params:
                    raise zope.interface.Invalid(f"The method {method_name} has the following required parameters missing from its signature: {', '.join(missing_params)}")
            return True
    except zope.interface.Invalid as e:
        raise e
    return False

